import React, {useEffect, useRef, useState} from "react";
import {toast} from "react-toastify";
import {Alert, Box, Button, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, Paper, Stack, Table, TableBody, TableCell, TableHead, TableRow, TextField, Typography} from "@mui/material";
import {Link, useSearchParams} from "react-router-dom";
import {getApiErrorMessage} from "../../api/errors";
import {getActiveFirmId} from "../../api/config";
import {useAuth} from "../../auth/AuthContext";
import {MainDiv, PageTitle} from "../../ui/commonStyled/commonStyled";
import {Receipt, StockLookup, useLazyLookupStockQuery, useReceiptHistoryQuery, useReceiptQuery, useLazyReceiptQuery, useReceiveStockMutation, useArchiveReceiptMutation, useRestoreReceiptMutation, useDeleteArchivedReceiptMutation, useClearReceiptArchiveMutation} from "./warehouseReceiptsApi";
import {newRequestId, positiveQuantity, ReceiptDraft, receiptPayload} from "./receiptDraft";
import ReceiptDetails from "./ReceiptDetails";

const emptyDraft = (): ReceiptDraft => ({requestId: newRequestId(), lines: [], comment: "", submitted: false});
const isManualReceipt = (receipt: Receipt) => receipt.transportWaybillId == null && receipt.sourceDocumentKind == null;
export default function WarehouseReceiptsPage() {
    const {user} = useAuth(); const [params] = useSearchParams(); const selectedReceipt = params.get("receipt") ?? "";
    const key = `vivotech.receipt.${getActiveFirmId()}.${user?.id}`;
    const [draft, setDraft] = useState<ReceiptDraft>(() => {try {const saved = JSON.parse(sessionStorage.getItem(key) ?? "null") as ReceiptDraft | null; return saved?.requestId && Array.isArray(saved.lines) ? saved : emptyDraft();} catch {return emptyDraft();}});
    const [scan, setScan] = useState(""); const [product, setProduct] = useState<StockLookup | null>(null); const [quantity, setQuantity] = useState("1");
    const [error, setError] = useState(""); const [lastReceipt, setLastReceipt] = useState<Receipt | null>(null); const [page, setPage] = useState(1);
    const [archived, setArchived] = useState(false); const [removing, setRemoving] = useState<string | null>(null); const [historyError, setHistoryError] = useState(""); const [historyBusy, setHistoryBusy] = useState(false);
    const [archiveReceipt] = useArchiveReceiptMutation(); const [restoreReceipt] = useRestoreReceiptMutation();
    const [deleteReceipt] = useDeleteArchivedReceiptMutation(); const [clearArchive] = useClearReceiptArchiveMutation();
    const scanRef = useRef<HTMLInputElement>(null); const quantityRef = useRef<HTMLInputElement>(null);
    const [lookup, lookupState] = useLazyLookupStockQuery(); const [receive, receiveState] = useReceiveStockMutation();
    const [checkReceipt] = useLazyReceiptQuery();
    const history = useReceiptHistoryQuery({page, archived}); const linked = useReceiptQuery(selectedReceipt, {skip: !selectedReceipt});
    const changeArchive = async (receipt: Receipt) => {
        setHistoryBusy(true); setHistoryError("");
        try {await (receipt.isArchived ? restoreReceipt(receipt.id) : archiveReceipt(receipt.id)).unwrap(); setLastReceipt(null); setPage(1);}
        catch (failure) {setHistoryError(getApiErrorMessage(failure, "Не удалось изменить архив приёмок."));}
        finally {setHistoryBusy(false);}
    };
    const remove = async () => {
        if (!removing) return;
        setHistoryBusy(true); setHistoryError("");
        try {await (removing === "all" ? clearArchive() : deleteReceipt(removing)).unwrap(); setRemoving(null); setLastReceipt(null); setPage(1); toast.success("История приёмок удалена. Остатки сохранены.");}
        catch (failure) {setHistoryError(getApiErrorMessage(failure, "Не удалось удалить историю приёмок.")); setRemoving(null);}
        finally {setHistoryBusy(false);}
    };
    useEffect(() => {sessionStorage.setItem(key, JSON.stringify(draft));}, [key, draft]);
    const resolve = async () => {setError(""); setProduct(null); if (!scan.trim()) return; try {const found = await lookup(scan.trim(), false).unwrap(); setProduct(found); setQuantity("1"); setTimeout(() => quantityRef.current?.focus(), 0);} catch (failure) {setError(getApiErrorMessage(failure, "Не удалось найти товар."));}};
    const add = () => {if (!product) return; const amount = positiveQuantity(quantity); if (amount === null) {setError("Введите количество больше нуля, не более 6 знаков после запятой."); return;}
        if (draft.lines.length >= 500 && !draft.lines.some(line => line.gtin === product.gtin)) {setError("В одной приёмке допустимо не больше 500 товаров."); return;}
        const current = draft.lines.find(line => line.gtin === product.gtin); const total = (current?.quantity ?? 0) + amount;
        if (total > 1e12) {setError("Количество превышает допустимый максимум."); return;}
        setDraft({...draft, lines: current ? draft.lines.map(line => line.gtin === product.gtin ? {...line, quantity: Math.round(total * 1e6) / 1e6} : line) : [...draft.lines, {...product, quantity: amount}]});
        setProduct(null); setScan(""); setError(""); scanRef.current?.focus();};
    const save = async () => {setError(""); const submitted = {...draft, submitted: true}; setDraft(submitted);
        try {const receipt = await receive(receiptPayload(submitted)).unwrap(); setLastReceipt(receipt); setDraft(emptyDraft()); setProduct(null); setScan(""); toast.success("Приёмка сохранена. Остатки обновлены."); scanRef.current?.focus();}
        catch (failure) {const status = (failure as {status?: unknown}).status; if (typeof status === "number" && status >= 400 && status < 500 && status !== 409) setDraft({...submitted, submitted: false}); if (status === 409) {
            try {const confirmed = await checkReceipt(submitted.requestId, false).unwrap(); setLastReceipt(confirmed); setDraft(emptyDraft()); setProduct(null); setScan(""); toast.success("Приёмка уже сохранена. Остатки обновлены."); return;}
            catch (checkFailure) {
                const checkStatus = (checkFailure as {status?: unknown}).status;
                if (checkStatus === 410) {setDraft(emptyDraft()); setProduct(null); setScan(""); setError("Приёмка уже проведена, её история удалена. Остатки сохранены. Можно начать новую приёмку."); return;}
                if (checkStatus === 404) setDraft({...submitted, submitted: false});
            }
        } setError(getApiErrorMessage(failure, "Ответ сервера не получен. Повторите сохранение: состав и номер приёмки сохранены."));}};
    return <MainDiv><Stack spacing={2}><PageTitle>Приёмка по GTIN</PageTitle><Typography color="text.secondary">Ручная приёмка с помощью 2D-сканера: отсканируйте GTIN, проверьте товар и введите количество. Остатки изменятся после сохранения всей приёмки. История файлов находится в разделе «Файлы для прихода».</Typography>
        {error && <Alert severity="error">{error} <Button component={Link} to="/catalogGeneration/file">Подготовить товар из ePass</Button></Alert>}
        {draft.submitted && <Alert severity="warning">Приёмка отправлялась на сервер. Состав сохранён до подтверждения, чтобы избежать повторного поступления. Нажмите «Повторить сохранение».</Alert>}
        <Paper variant="outlined" sx={{p: 2}}><Stack spacing={2}><Box component="form" aria-label="Поиск сканированного товара" onSubmit={event => {event.preventDefault(); void resolve();}} sx={{display: "flex", gap: 1}}><TextField label="Сканируйте GTIN" autoFocus inputRef={scanRef} fullWidth value={scan} disabled={draft.submitted || lookupState.isFetching} onChange={event => {setScan(event.target.value); setProduct(null);}}/><Button type="submit" disabled={!scan.trim() || draft.submitted || lookupState.isFetching}>{lookupState.isFetching ? <CircularProgress size={20}/> : "Найти"}</Button></Box>
            {product && <Box component="form" aria-label="Количество сканированного товара" onSubmit={event => {event.preventDefault(); add();}}><Typography fontWeight={700}>{product.name}</Typography><Typography color="text.secondary">{product.gtin} · Сейчас на складе: {product.currentStock}</Typography><Stack direction="row" gap={1} mt={1}><TextField label="Количество к приёмке" inputRef={quantityRef} inputProps={{inputMode: "decimal"}} value={quantity} onChange={event => setQuantity(event.target.value)}/><Button type="submit" variant="contained">Добавить в приёмку</Button></Stack></Box>}
            {draft.lines.length > 0 && <Table size="small"><TableHead><TableRow><TableCell>Товар / GTIN</TableCell><TableCell>Количество</TableCell><TableCell/></TableRow></TableHead><TableBody>{draft.lines.map(line => <TableRow key={line.gtin}><TableCell>{line.name}<Typography variant="caption" display="block">{line.gtin}</Typography></TableCell><TableCell>{line.quantity}</TableCell><TableCell><Button disabled={draft.submitted} onClick={() => setDraft({...draft, lines: draft.lines.filter(item => item.gtin !== line.gtin)})}>Убрать</Button></TableCell></TableRow>)}</TableBody></Table>}
            <TextField label="Комментарий к приёмке" multiline helperText="Укажите партии, сроки годности, состояние и расхождения с документами." value={draft.comment} disabled={draft.submitted} inputProps={{maxLength: 1000}} onChange={event => setDraft({...draft, comment: event.target.value})}/><Button variant="contained" disabled={!draft.lines.length || receiveState.isLoading} onClick={() => void save()}>{receiveState.isLoading ? "Сохраняем…" : draft.submitted ? "Повторить сохранение" : `Принять на склад (${draft.lines.length})`}</Button>
        </Stack></Paper>
        {lastReceipt && <><Alert severity="success">Приёмка сохранена. Остатки обновлены.</Alert><ReceiptDetails receipt={lastReceipt}/></>}
        {linked.data && (isManualReceipt(linked.data) ? <ReceiptDetails receipt={linked.data}/> : <Alert severity="info">Этот приход относится к файлу для прихода. <Button component={Link} to={`/invoices/receipts/${linked.data.id}`}>Открыть проведённый приход</Button></Alert>)} {linked.isError && <Alert severity="error">Приёмка по ссылке недоступна.</Alert>}
        <Typography variant="h6">История ручных приёмок по GTIN</Typography>
        <Stack direction="row" gap={1}><Button variant={!archived ? "contained" : "outlined"} disabled={historyBusy} onClick={() => {setArchived(false); setPage(1);}}>Активные приёмки</Button><Button variant={archived ? "contained" : "outlined"} disabled={historyBusy} onClick={() => {setArchived(true); setPage(1);}}>Архив приёмок</Button>
            {archived && <Button color="error" disabled={historyBusy || history.isFetching || history.isError || !history.data?.length} onClick={() => setRemoving("all")}>Очистить архив приёмок</Button>}</Stack>
        <Typography color="text.secondary">Архивация и удаление истории не меняют складские остатки.</Typography>
        {historyError && <Alert severity="error">{historyError}</Alert>}
        {history.isLoading && <CircularProgress/>}{history.isError && <Alert severity="error">Не удалось загрузить журнал. <Button onClick={() => void history.refetch()}>Повторить</Button></Alert>}
        {history.data?.length === 0 && <Typography color="text.secondary">{archived ? "Архив приёмок пуст." : "Приёмок пока нет."}</Typography>}{history.currentData?.filter(isManualReceipt).map(receipt => <ReceiptDetails key={receipt.id} receipt={receipt}>
            <Button disabled={historyBusy || history.isFetching} onClick={() => void changeArchive(receipt)}>{receipt.isArchived ? "Восстановить приёмку" : "В архив"}</Button>
            {receipt.isArchived && <Button color="error" disabled={historyBusy || history.isFetching} onClick={() => setRemoving(receipt.id)}>Удалить приёмку навсегда</Button>}
        </ReceiptDetails>)}
        <Stack direction="row" gap={1}><Button disabled={page === 1} onClick={() => setPage(page - 1)}>Назад</Button><Typography alignSelf="center">Страница {page}</Typography><Button disabled={(history.data?.length ?? 0) < 25} onClick={() => setPage(page + 1)}>Далее</Button></Stack>
        <Dialog open={removing !== null} onClose={() => {if (!historyBusy) setRemoving(null);}} aria-labelledby="delete-receipts-title"><DialogTitle id="delete-receipts-title">{removing === "all" ? "Очистить архив ручных приёмок?" : "Удалить историю приёмки навсегда?"}</DialogTitle><DialogContent>Записи и строки приёмок будут физически удалены из базы данных. Восстановление невозможно. Остатки товаров и история файлов для прихода сохранятся.</DialogContent><DialogActions><Button disabled={historyBusy} onClick={() => setRemoving(null)}>Отмена</Button><Button color="error" disabled={historyBusy} onClick={() => void remove()}>Удалить</Button></DialogActions></Dialog>
    </Stack></MainDiv>;
}
